/* =====================================================================================
   DemandIQ - seed_data.sql                                           (SQL Server / SSMS)
   Database : [B1A-S6-T3]  (must already exist; run create_tables.sql first)
   Content  : realistic, interconnected seed data for all 17 tables of the DemandIQ ER v3.

   ALL DATES ARE RELATIVE TO THE MOMENT YOU RUN THE SCRIPT (@Today = server date):
     * Cleaned sales history : @Today-135  ..  @Today-8   (128 consecutive days, 4 uploads)
     * Pending upload (DS-0007): @Today-7  ..  @Today-1   (7 days waiting to be cleaned)
     * Inventory snapshots   : one per SKU per day, @Today-135 .. @Today-1
     * Forecast runs         : horizons 7 / 30 / 90 days, history ends @Today-8 (plus two
                               earlier checkpoints whose forecast dates overlap real sales)
     * Activity / sessions / reports / errors / reorders spread over the same period.

   The script runs in ONE transaction: it either loads everything or nothing.
   @ResetExisting = 1 (default) first empties the 17 DemandIQ tables so the script can be
   re-run safely. Set it to 0 to make the script stop if any table already has rows.
   ===================================================================================== */
USE [B1A-S6-T3];
GO

SET NOCOUNT ON;
SET XACT_ABORT ON;

DECLARE @ResetExisting BIT = 1;

DECLARE @Today DATE = CAST(SYSDATETIME() AS DATE);
DECLARE @Now   DATETIMEOFFSET(0) = SYSDATETIMEOFFSET();
DECLARE @T0    DATETIMEOFFSET(0) = TODATETIMEOFFSET(CAST(@Today AS DATETIME2(0)), DATEPART(TZOFFSET, SYSDATETIMEOFFSET()));

BEGIN TRY
BEGIN TRANSACTION;

IF @ResetExisting = 1
BEGIN
    DELETE FROM dbo.error_log;
    DELETE FROM dbo.activity_log;
    DELETE FROM dbo.reports;
    DELETE FROM dbo.reorders;
    DELETE FROM dbo.forecast;
    DELETE FROM dbo.inventory;
    DELETE FROM dbo.sales_records;
    DELETE FROM dbo.datasets;
    DELETE FROM dbo.products;
    DELETE FROM dbo.product_families;
    DELETE FROM dbo.sessions;
    DELETE FROM dbo.users;
    DELETE FROM dbo.role_report_types;
    DELETE FROM dbo.role_permissions;
    DELETE FROM dbo.role_screens;
    DELETE FROM dbo.screens;
    DELETE FROM dbo.roles;
END
ELSE IF EXISTS (SELECT 1 FROM dbo.roles) OR EXISTS (SELECT 1 FROM dbo.users) OR EXISTS (SELECT 1 FROM dbo.sales_records)
BEGIN
    THROW 50001, 'DemandIQ tables already contain data. Set @ResetExisting = 1 to replace it.', 1;
END


-- 1. roles -----------------------------------------------------------------------------

-- 2. screens ---------------------------------------------------------------------------

-- 3. role_screens (which role can open which screen) ------------------------------------

-- 4. role_permissions (action matrix: Yes / View / Review / No) --------------------------

-- 5. role_report_types (report access per role + report details) ------------------------

-- 6. users (passwords: PBKDF2-SHA256 hashes in passlib format; see EXECUTION_GUIDE.md) --

-- 7. sessions ----------------------------------------------------------------------------

-- 8. product_families (product categories) ----------------------------------------------

-- 9. products ----------------------------------------------------------------------------

-- 10. datasets (uploads: Pending / Completed / Not started) ------------------------------

-- 11. sales_records (3,913 rows: 3,709 cleaned + 204 pending) ----------------

-- 12. inventory (daily snapshot per SKU, 2,025 rows) --------------------------------

-- 13. forecast (79 runs, 2,787 daily prediction rows) ---------------------------

-- 14. reorders (66 rows) ---------------------------------------------------------

-- 15. reports (73 rows) ----------------------------------------------------------

-- 16. activity_log (1,481 rows) ----------------------------------------------------

-- 17. error_log (31 rows) -----------------------------------------------------------

COMMIT TRANSACTION;
PRINT 'DemandIQ seed data loaded successfully.';
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    PRINT 'Seed load FAILED - transaction rolled back.';
    THROW;
END CATCH;
GO

-- Quick check: rows per table
SELECT 'roles' AS table_name, COUNT(*) AS row_count FROM dbo.roles UNION ALL
SELECT 'screens', COUNT(*) FROM dbo.screens UNION ALL
SELECT 'role_screens', COUNT(*) FROM dbo.role_screens UNION ALL
SELECT 'role_permissions', COUNT(*) FROM dbo.role_permissions UNION ALL
SELECT 'role_report_types', COUNT(*) FROM dbo.role_report_types UNION ALL
SELECT 'users', COUNT(*) FROM dbo.users UNION ALL
SELECT 'sessions', COUNT(*) FROM dbo.sessions UNION ALL
SELECT 'product_families', COUNT(*) FROM dbo.product_families UNION ALL
SELECT 'products', COUNT(*) FROM dbo.products UNION ALL
SELECT 'datasets', COUNT(*) FROM dbo.datasets UNION ALL
SELECT 'sales_records', COUNT(*) FROM dbo.sales_records UNION ALL
SELECT 'inventory', COUNT(*) FROM dbo.inventory UNION ALL
SELECT 'forecast', COUNT(*) FROM dbo.forecast UNION ALL
SELECT 'reorders', COUNT(*) FROM dbo.reorders UNION ALL
SELECT 'reports', COUNT(*) FROM dbo.reports UNION ALL
SELECT 'activity_log', COUNT(*) FROM dbo.activity_log UNION ALL
SELECT 'error_log', COUNT(*) FROM dbo.error_log;
GO
